"""Exact finite gauge-relative source and observer instruments (research only).

A gauge map is DECLARED and checked against both the problem target and
source dynamics. This module cannot authenticate that a physical symmetry
is genuine. All stochastic model entries are exact Fractions.
"""
from __future__ import annotations
from fractions import Fraction as Q


def _permutation(p, n):
    return len(p) == n and set(p) == set(range(n))


def group_closure(generators, n):
    """Finite transformation group generated by supplied permutations."""
    if n < 1 or any(not _permutation(g,n) for g in generators):
        raise ValueError('finite nonempty state set and permutation generators required')
    ident=tuple(range(n)); seen={ident}; todo=[ident]
    while todo:
        a=todo.pop()
        for g in generators:
            c=tuple(g[a[x]] for x in range(n))
            if c not in seen:
                seen.add(c); todo.append(c)
    return tuple(sorted(seen))


def orbit_partition(n, generators):
    group=group_closure(generators,n)
    remaining=set(range(n)); ans=[]
    while remaining:
        x=min(remaining)
        orbit=frozenset(g[x] for g in group)
        remaining.difference_update(orbit)
        ans.append(tuple(sorted(orbit)))
    return tuple(ans)


def gauge_invariant(values, generators):
    n=len(values)
    return all(_permutation(g,n) and all(values[g[x]]==values[x] for x in range(n))
               for g in generators)


def equivariant_anchor(anchor, source_gens, reference_gens, reference_size):
    n=len(anchor)
    if (len(source_gens)!=len(reference_gens) or
        any(not isinstance(a,int) or not 0<=a<reference_size for a in anchor)):
        return False
    return all(_permutation(g,n) and _permutation(h,reference_size)
               and all(anchor[g[x]]==h[anchor[x]] for x in range(n))
               for g,h in zip(source_gens,reference_gens))


def relational_readout(anchor, value_table):
    if len(anchor)!=len(value_table):raise ValueError('reference/source mismatch')
    if not value_table or not value_table[0]:raise ValueError('nonempty relational readout')
    k=len(value_table[0])
    if any(len(row)!=k or not isinstance(anchor[x],int) or not 0<=anchor[x]<k
           for x,row in enumerate(value_table)):
        raise ValueError('inconsistent reference index')
    return tuple(value_table[x][anchor[x]] for x in range(len(anchor)))


def diagonal_invariant(value_table, source_gens, reference_gens):
    n=len(value_table)
    k=len(value_table[0])
    return all(_permutation(g,n) and _permutation(h,k)
               and all(value_table[g[x]][h[a]]==value_table[x][a]
                       for x in range(n) for a in range(k))
               for g,h in zip(source_gens,reference_gens))


def equivariant_transition(transition, gauge_generators):
    n=len(transition)
    if any(not isinstance(y,int) or not 0<=y<n for y in transition):
        return False
    return all(_permutation(g,n) and all(transition[g[x]]==g[transition[x]] for x in range(n))
               for g in gauge_generators)


def action_descends(readout, transition):
    """Target/report-fiber preservation, not merely gauge equivariance."""
    if len(readout)!=len(transition):raise ValueError('different state sets')
    return all(readout[i]!=readout[j] or readout[transition[i]]==readout[transition[j]]
               for i in range(len(readout)) for j in range(len(readout)))


def genuine_gauge_orbits_differ(readout, gauge_generators):
    return gauge_invariant(readout,gauge_generators)


def xor_carrier():
    """s,r bits; g flips both. Physical variable is s XOR r."""
    states=tuple(range(4))
    gauge=tuple(x^3 for x in states)
    anchor=tuple(x&1 for x in states)
    reference_gauge=(1,0)
    value_table=tuple(tuple((x>>1)^a for a in (0,1)) for x in states)
    physical=tuple((x>>1)^(x&1) for x in states)
    physical_flip=tuple(x^2 for x in states)
    return (gauge,anchor,reference_gauge,value_table,physical,physical_flip)


def hidden_carrier():
    """s,r,h bits; gauge changes s,r; hidden h affects future parity."""
    states=tuple(range(8))
    gauge=tuple(x^6 for x in states)
    report=tuple(((x>>2)&1)^((x>>1)&1) for x in states)
    hidden=tuple(x&1 for x in states)
    source_step=tuple(x^(4*(x&1)) for x in states)
    return gauge,report,hidden,source_step


def joint_model(raw_absolute=False, accuracy=Q(3,4)):
    """2-bit carrier: physical flip s; emitted old parity or, hostile, raw s."""
    if not isinstance(accuracy,(int,Q)) or not Q(0)<accuracy<Q(1):
        raise ValueError('nontrivial rational accuracy')
    gauge,anchor,rg,table,rel,T=xor_carrier()
    out=[]
    for x in range(4):
        row=[[Q(0),Q(0)] for _ in range(4)]
        truth=(x>>1) if raw_absolute else rel[x]
        row[T[x]][truth]=Q(accuracy)
        row[T[x]][1-truth]=Q(1)-Q(accuracy)
        out.append(tuple(tuple(c) for c in row))
    return tuple(out)


def validate_joint(joint):
    n=len(joint)
    if n<1 or not joint[0] or not joint[0][0]:return False
    k=len(joint[0][0])
    return all(len(row)==n and all(len(cell)==k for cell in row)
               and all(type(v) in (int,Q) and v>=0 for cell in row for v in cell)
               and sum((v for cell in row for v in cell),Q(0))==1 for row in joint)


def joint_gauge_covariant(joint, gauge_generators, output_actions=None):
    """Output transformations default to identity on the observable alphabet."""
    if not validate_joint(joint):return False
    n=len(joint); k=len(joint[0][0]); id_o=tuple(range(k))
    output_actions=output_actions if output_actions is not None else tuple(id_o for _ in gauge_generators)
    if len(output_actions)!=len(gauge_generators):return False
    return all(_permutation(g,n) and _permutation(h,k)
               and all(joint[g[x]][g[xp]][h[o]]==joint[x][xp][o]
                       for x in range(n) for xp in range(n) for o in range(k))
               for g,h in zip(gauge_generators,output_actions))


def quotient_joint(joint, gauge_generators):
    """Lump source J through gauge orbits; fail closed if not gauge-covariant."""
    if not joint_gauge_covariant(joint,gauge_generators):
        raise ValueError('joint source law is not gauge-covariant')
    n=len(joint); k=len(joint[0][0]); orbits=orbit_partition(n,gauge_generators)
    rows=[]
    for orbit in orbits:
        x=orbit[0]
        rows.append(tuple(tuple(sum((joint[x][xp][o] for xp in dst),Q(0))
                                for o in range(k)) for dst in orbits))
    return orbits,tuple(rows)


def source_cost_invariant(cost_table, gauge_generators):
    n=len(cost_table)
    return all(_permutation(g,n) and all(cost_table[g[x]]==cost_table[x] for x in range(n))
               for g in gauge_generators)


def filter_current(prior, joint, outcome):
    """Exact filtering on whole state X, returns (evidence probability, posterior)."""
    n=len(joint)
    if len(prior)!=n or not validate_joint(joint):raise ValueError('source/prior mismatch')
    if (type(outcome)!=int or not 0<=outcome<len(joint[0][0]) or
        any(type(p) not in (Q,int) or p<0 for p in prior) or sum(prior,Q(0))!=1):
        raise ValueError('invalid observation/prior')
    mass=tuple(sum((prior[x]*joint[x][xp][outcome] for x in range(n)),Q(0)) for xp in range(n))
    z=sum(mass,Q(0))
    return (z,tuple(v/z for v in mass)) if z>0 else (Q(0),None)


def push_to_orbits(prior,orbits):
    return tuple(sum((prior[x] for x in orbit),Q(0)) for orbit in orbits)


def expected_cost(prior,cost_table):
    return sum((prior[x]*cost_table[x] for x in range(len(prior))),Q(0))
